CREATE TABLE competitions(id text PRIMARY KEY,name text NOT NULL,mode text NOT NULL CHECK(mode IN ('MOCK','DELAYED','HISTORICAL')));
CREATE TABLE seasons(id text PRIMARY KEY,competition_id text NOT NULL REFERENCES competitions,name text NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,CHECK(ends_at>starts_at));
CREATE TABLE stages(id text PRIMARY KEY,season_id text NOT NULL REFERENCES seasons,name text NOT NULL);
CREATE TABLE clubs(id text PRIMARY KEY,name text NOT NULL);
CREATE TABLE club_seasons(club_id text REFERENCES clubs,season_id text REFERENCES seasons,PRIMARY KEY(club_id,season_id));
CREATE TABLE players(id text PRIMARY KEY,name text NOT NULL,position text NOT NULL CHECK(position IN ('GK','DF','MF','FW')),born_on date NOT NULL);
CREATE TABLE player_memberships(id text PRIMARY KEY,player_id text NOT NULL REFERENCES players,club_id text NOT NULL REFERENCES clubs,starts_at timestamptz NOT NULL,ends_at timestamptz,CHECK(ends_at IS NULL OR ends_at>starts_at));
CREATE TABLE player_seasons(player_id text REFERENCES players,season_id text REFERENCES seasons,minutes integer NOT NULL CHECK(minutes>=0),goals integer NOT NULL CHECK(goals>=0),assists integer NOT NULL CHECK(assists>=0),PRIMARY KEY(player_id,season_id));
CREATE TABLE fixtures(id text PRIMARY KEY,season_id text NOT NULL REFERENCES seasons,stage_id text REFERENCES stages,home_id text NOT NULL REFERENCES clubs,away_id text NOT NULL REFERENCES clubs,kickoff_at timestamptz NOT NULL,status text NOT NULL,home_score integer CHECK(home_score>=0),away_score integer CHECK(away_score>=0),mode text NOT NULL CHECK(mode IN ('MOCK','DELAYED','HISTORICAL')),revision integer NOT NULL DEFAULT 1 CHECK(revision>0),CHECK(home_id<>away_id));
CREATE INDEX fixture_schedule ON fixtures(season_id,kickoff_at);
CREATE TABLE fixture_events(id text PRIMARY KEY,fixture_id text NOT NULL REFERENCES fixtures,logical_id text NOT NULL,revision integer NOT NULL CHECK(revision>0),period smallint NOT NULL CHECK(period BETWEEN 1 AND 5),clock_ms integer NOT NULL CHECK(clock_ms>=0),kind text NOT NULL,player_id text REFERENCES players,occurred_at timestamptz NOT NULL,payload jsonb NOT NULL DEFAULT '{}',UNIQUE(fixture_id,logical_id,revision));
CREATE INDEX fixture_timeline ON fixture_events(fixture_id,period,clock_ms);
CREATE TABLE lineups(fixture_id text REFERENCES fixtures,player_id text REFERENCES players,club_id text NOT NULL REFERENCES clubs,starter boolean NOT NULL,PRIMARY KEY(fixture_id,player_id));
CREATE TABLE team_stats(fixture_id text REFERENCES fixtures,club_id text REFERENCES clubs,shots integer CHECK(shots>=0),possession numeric CHECK(possession BETWEEN 0 AND 100),PRIMARY KEY(fixture_id,club_id));
CREATE TABLE player_stats(fixture_id text REFERENCES fixtures,player_id text REFERENCES players,minutes integer CHECK(minutes BETWEEN 0 AND 130),goals integer CHECK(goals>=0),PRIMARY KEY(fixture_id,player_id));
CREATE TABLE provider_mappings(provider text,entity_type text,external_id text,internal_id text NOT NULL,PRIMARY KEY(provider,entity_type,external_id));
CREATE TABLE provider_coverage(fixture_id text REFERENCES fixtures,provider text,has_lineups boolean NOT NULL DEFAULT false,has_tracking boolean NOT NULL DEFAULT false,has_xg boolean NOT NULL DEFAULT false,observed_at timestamptz NOT NULL,PRIMARY KEY(fixture_id,provider));
CREATE TABLE users(id text PRIMARY KEY,username text UNIQUE NOT NULL,password_hash text);
CREATE TABLE sessions(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users,token_hash text UNIQUE NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE user_preferences(user_id text PRIMARY KEY REFERENCES users,timezone text NOT NULL DEFAULT 'UTC',preferences jsonb NOT NULL DEFAULT '{}');
CREATE TABLE rating_models(id text PRIMARY KEY,version integer NOT NULL,weights jsonb NOT NULL);
CREATE TABLE simulation_runs(id text PRIMARY KEY,user_id text REFERENCES users,seed bigint NOT NULL,engine_version text NOT NULL,status text NOT NULL);
CREATE TABLE fantasy_seasons(id text PRIMARY KEY,season_id text REFERENCES seasons,rules jsonb NOT NULL);
CREATE TABLE news_metadata(id text PRIMARY KEY,title text NOT NULL,source text NOT NULL,published_at timestamptz NOT NULL,mode text NOT NULL CHECK(mode IN ('MOCK','HISTORICAL','DELAYED')));
CREATE TABLE idempotency_keys(scope text,key text,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(scope,key));
CREATE TABLE event_outbox(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,event_id text UNIQUE NOT NULL,aggregate_id text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),published_at timestamptz);
CREATE INDEX pending_outbox ON event_outbox(id) WHERE published_at IS NULL;
CREATE TABLE demo_catalogue(section text NOT NULL,id text NOT NULL,name text NOT NULL,detail text NOT NULL,value text NOT NULL,PRIMARY KEY(section,id));
